from __future__ import annotations

import math
from fractions import Fraction
from typing import Iterable


#
# This module belongs to the algebraic layer, not to the runtime.
#
# DECAY is naturally parameterized by:
#
#     lambda = 1 / tau
#
# Consecutive decays compose additively in lambda:
#
#     lambda_eff = sum(lambda_i)
#
# Fraction is used here so rates generated by canonicalization such as
# 3/2, 3, 7/2, ... remain exact at the algebraic level.
#


MAX_TAU_DENOMINATOR = 1_000_000


def tau_to_fraction(
    tau: float,
) -> Fraction:
    """
    Recover the intended rational tau when possible.

    Examples:

        2.0                -> 2
        1.0                -> 1
        0.666666666666...  -> 2/3
        0.333333333333...  -> 1/3
        0.285714285714...  -> 2/7
    """

    if isinstance(tau, bool):
        raise TypeError(
            "tau must be a positive real number"
        )

    tau = float(tau)

    if (
        not math.isfinite(tau)
        or tau <= 0.0
    ):
        raise ValueError(
            "tau must be finite and > 0"
        )

    return Fraction(
        str(tau)
    ).limit_denominator(
        MAX_TAU_DENOMINATOR
    )


def tau_to_rate(
    tau: float,
) -> Fraction:
    """
    Convert tau to the exact algebraic decay rate:

        lambda = 1 / tau
    """

    tau_fraction = tau_to_fraction(
        tau
    )

    return Fraction(
        tau_fraction.denominator,
        tau_fraction.numerator,
    )


def rate_to_tau(
    rate: Fraction,
) -> float:
    """
    Convert an exact positive algebraic rate back to the runtime tau
    representation.
    """

    if not isinstance(rate, Fraction):
        raise TypeError(
            "rate must be a Fraction"
        )

    if rate <= 0:
        raise ValueError(
            "rate must be > 0"
        )

    tau = Fraction(
        rate.denominator,
        rate.numerator,
    )

    return float(tau)


def combine_decay_taus(
    taus: Iterable[float],
) -> float:
    """
    Combine one or more consecutive decay constants algebraically.

        lambda_eff
            =
        sum(1 / tau_i)

    and:

        tau_eff
            =
        1 / lambda_eff

    The summation itself is exact because lambda is represented with
    Fraction.
    """

    values = tuple(
        taus
    )

    if not values:
        raise ValueError(
            "at least one tau is required"
        )

    effective_rate = sum(
        (
            tau_to_rate(tau)
            for tau in values
        ),
        start=Fraction(0, 1),
    )

    return rate_to_tau(
        effective_rate
    )


def effective_rate(
    taus: Iterable[float],
) -> Fraction:
    """
    Return the exact effective lambda without converting back to float.
    """

    values = tuple(
        taus
    )

    if not values:
        raise ValueError(
            "at least one tau is required"
        )

    return sum(
        (
            tau_to_rate(tau)
            for tau in values
        ),
        start=Fraction(0, 1),
    )
